android.extraProguardRules:
# R8 strips anything it cannot see a reference to, and native modules are
# reached by reflection from JS, so they must be kept explicitly. A stripped
# class here fails only at runtime in a release build, which for a wallet can
# mean a signing path that dies mid-transaction.
-keep class com.facebook.react.** { *; }
-keep class com.facebook.hermes.** { *; }
-keep class com.facebook.jni.** { *; }
-keepclassmembers class * { @com.facebook.proguard.annotations.DoNotStrip *; }
-keepclassmembers class * { @com.facebook.common.internal.DoNotStrip *; }
-keep @com.facebook.proguard.annotations.DoNotStrip class *
-keep class expo.modules.** { *; }
-keep class com.swmansion.** { *; }
-keep class com.th3rdwave.safeareacontext.** { *; }
-keep class org.bouncycastle.** { *; }
-keep class org.spongycastle.** { *; }
-dontwarn okhttp3.**
-dontwarn okio.**
-dontwarn javax.annotation.**
# R8 aborts when a referenced class is missing. These are all references from
# libraries into JDK/desktop APIs that do not exist on Android: JNA reaching
# java.awt, spongycastle's LDAP CertStore reaching javax.naming, and its
# optional post-quantum ciphers. None of it is reachable at runtime here, so
# suppressing the warning is correct rather than keeping the classes.
-dontwarn java.awt.**
-dontwarn javax.naming.**
-dontwarn com.sun.jna.**
-dontwarn org.spongycastle.**
-dontwarn org.bouncycastle.**
-dontwarn java.beans.**
-dontwarn javax.swing.**
